// D&D 5e SRD API: read-only 2014 catalog. Selected data stays in local storage.
const API='https://www.dnd5eapi.co';
let catType='spells',catQuery='',catLevel='',catClass='',catResults=[],catDetail=null,catError='',catLoading=false,catSequence=0;
const catKinds={spells:['Incantesimi e trucchetti','spells'],metamagic:['Metamagie','classes/sorcerer/features'],classes:['Classi','classes'],subclasses:['Sottoclassi','subclasses'],backgrounds:['Background','backgrounds'],races:['Razze','races'],subraces:['Sottorazze','subraces'],traits:['Tratti razziali','traits'],features:['Privilegi di classe','features'],feats:['Talenti','feats'],equipment:['Equipaggiamento','equipment'],magicitems:['Oggetti magici','magic-items']};
function catalog(){return title('Catalogo SRD','Esplora le opzioni del regolamento 5e 2014 e aggiungile al tuo personaggio.')+`<div class="grid">${card('ESPLORA IL CATALOGO',`<p class="sub">Contenuti SRD 5.1 forniti da D&D 5e SRD API. Nomi e descrizioni sono in inglese. Alcuni contenuti dei manuali non sono inclusi. <a href="https://www.dnd5eapi.co/" target="_blank" rel="noopener">Fonte ↗</a> · SRD 5.1 © Wizards of the Coast, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>.</p><div class="catalog-filters"><select id="catType" aria-label="Categoria">${Object.entries(catKinds).map(([k,v])=>`<option value="${k}" ${k===catType?'selected':''}>${v[0]}</option>`).join('')}</select><input class="search" id="catSearch" placeholder="Cerca per nome in inglese…" value="${esc(catQuery)}">${catType==='spells'?`<select id="catLevel" aria-label="Livello incantesimo"><option value="">Tutti i livelli</option>${Array.from({length:10},(_,i)=>`<option value="${i}" ${catLevel===String(i)?'selected':''}>${i===0?'Trucchetti':'Livello '+i}</option>`).join('')}</select><select id="catClass" aria-label="Classe incantesimo"><option value="">Tutte le classi</option>${['bard','cleric','druid','paladin','ranger','sorcerer','warlock','wizard'].map(c=>`<option ${catClass===c?'selected':''} value="${c}">${c}</option>`).join('')}</select>`:''}</div><div id="catalog-status" class="sub"></div><div class="catalog-layout"><div id="catalog-list" class="catalog-list"></div><div id="catalog-detail" class="catalog-detail"></div></div>`,'','D&D 5E · 2014')}${card('OPZIONI SELEZIONATE',`<div id="catalog-saved">${savedCatalog()}</div>`,'','SALVATE NELLA SCHEDA')}</div>`}
function savedCatalog(){let a=state.catalog||[];return a.length?a.map((x,i)=>`<div class="list-item"><div><strong>${esc(x.name)}</strong> <span class="tag">${esc(x.kind)}</span><p>${esc(x.description||'Nessuna descrizione disponibile.')}</p></div><button class="secondary" data-cat-remove="${i}">Rimuovi</button></div>`).join(''):'<div class="empty"><b>Nessuna opzione selezionata</b>Le caratteristiche aggiunte dal catalogo compariranno qui con la loro descrizione.</div>'}
function catPath(){if(catType==='spells'){let base=catClass?`classes/${catClass}/spells`:'spells';return '/api/2014/'+base+(catLevel!==''?'?level='+catLevel:'')}return '/api/2014/'+catKinds[catType][1]}
async function loadCatalog(){const seq=++catSequence;catLoading=true;catError='';catDetail=null;catResults=[];drawCatalog();try{let res=await fetch(API+catPath());if(!res.ok)throw Error('HTTP '+res.status);let data=await res.json();if(seq!==catSequence)return;catResults=Array.isArray(data.results)?data.results:[];if(catType==='metamagic')catResults=catResults.filter(x=>x.index.startsWith('metamagic-')&&!/^metamagic-\d+$/.test(x.index));}catch(e){if(seq!==catSequence)return;catError='Impossibile raggiungere il catalogo. Controlla la connessione e riprova.'}finally{if(seq===catSequence){catLoading=false;drawCatalog()}}}
function drawCatalog(){let list=$('#catalog-list'),detail=$('#catalog-detail'),status=$('#catalog-status');if(!list)return;let results=catResults.filter(x=>x.name.toLowerCase().includes(catQuery.toLowerCase()));status.textContent=catLoading?'Caricamento del catalogo…':catError||`${results.length} risultati · Seleziona una voce per leggere i dettagli.`;list.innerHTML=catError?'<button class="secondary" id="catRetry">Riprova</button>':results.length?results.map((x,i)=>`<button class="catalog-result ${catDetail?.index===x.index?'selected':''}" data-cat-index="${esc(x.index)}"><span>${esc(x.name)}</span><span>›</span></button>`).join(''):'<div class="empty">'+(catLoading?'Caricamento…':'Nessun risultato.')+'</div>';detail.innerHTML=catDetail?detailHTML(catDetail):'<div class="empty"><b>Apri una voce</b>Qui vedrai la descrizione e potrai aggiungerla alla scheda.</div>'}
function description(d){let parts=[];if(Array.isArray(d.desc))parts.push(...d.desc);else if(d.desc)parts.push(d.desc);if(Array.isArray(d.higher_level)&&d.higher_level.length)parts.push('At higher levels: '+d.higher_level.join(' '));for(let k of ['age','alignment','size_description','language_desc','starting_proficiencies_desc'])if(d[k])parts.push(typeof d[k]==='string'?d[k]:'');if(d.hit_die)parts.push('Hit die: d'+d.hit_die);if(d.speed!==undefined)parts.push('Speed: '+d.speed+' feet');if(Array.isArray(d.ability_bonuses)&&d.ability_bonuses.length)parts.push('Ability bonuses: '+d.ability_bonuses.map(x=>x.ability_score?.name+' +'+x.bonus).join(', '));if(d.equipment_category)parts.push('Category: '+d.equipment_category.name);if(d.weight!==undefined)parts.push('Weight: '+d.weight+' lb');if(d.cost)parts.push('Cost: '+d.cost.quantity+' '+d.cost.unit);return parts.filter(Boolean).join('\n\n')}
function detailHTML(d){let text=description(d),info=catType==='spells'?`<p class="sub">${d.level===0?'Trucchetto':'Livello '+d.level} · ${esc(d.school?.name||'')} · ${esc(d.casting_time||'')} · ${esc(d.range||'')} · ${esc(d.duration||'')} · ${esc((d.components||[]).join(', '))}${d.material?' ('+esc(d.material)+')':''}</p>`:'';return `<div class="eyebrow">${esc(catKinds[catType][0])} · SRD 2014</div><h3>${esc(d.name)}</h3>${info}<p class="catalog-description">${esc(text||'Nessuna descrizione testuale disponibile per questa voce nell’API.')}</p><button class="primary" id="catAdd">+ Aggiungi alla scheda</button><p id="catMessage" class="sub"></p>`}
async function openCatItem(index){let entry=catResults.find(x=>x.index===index);if(!entry)return;let target=$('#catalog-detail');target.innerHTML='<p class="sub">Caricamento descrizione…</p>';try{let res=await fetch(API+entry.url);if(!res.ok)throw Error();let d=await res.json();if(!$('#catalog-detail'))return;catDetail=d;drawCatalog()}catch{target.innerHTML='<p class="sub">Impossibile caricare i dettagli. Seleziona nuovamente la voce per riprovare.</p>'}}
function addCatalog(){let d=catDetail;if(!d)return;if(catType==='spells'){if(state.spells.some(x=>x.srdIndex===d.index)){$('#catMessage').textContent='Questo incantesimo è già nel grimorio.';return}state.spells.push({nome:d.name,livello:String(d.level),scuola:d.school?.name||'',lancio:d.casting_time||'',gittata:d.range||'',durata:d.duration||'',componenti:(d.components||[]).join(', ')+(d.material?' ('+d.material+')':''),descrizione:description(d),effetti:'',srdIndex:d.index});}else if(catType==='equipment'||catType==='magicitems'){if(state.items.some(x=>x.srdIndex===d.index)){$('#catMessage').textContent='Questo oggetto è già presente nell’inventario.';return}state.items.push({nome:d.name,quantita:1,tipo:catType==='magicitems'?'Oggetti magici':'Equipaggiamento',peso:d.weight!=null?(d.weight*0.45359237).toFixed(2):'',valore:'',descrizione:description(d),equipaggiato:false,srdIndex:d.index})}else{state.catalog ||= [];if(state.catalog.some(x=>x.index===d.index&&x.type===catType)){$('#catMessage').textContent='Questa opzione è già stata aggiunta.';return}state.catalog.push({type:catType,index:d.index,name:d.name,kind:catKinds[catType][0],description:description(d)});if(catType==='classes')state.identity.classe=d.name;if(catType==='subclasses')state.identity.sottoclasse=d.name;if(catType==='races')state.identity.razza=d.name;if(catType==='backgrounds')state.identity.background=d.name;}save();$('#catalog-saved').innerHTML=savedCatalog();$('#catMessage').textContent=catType==='spells'?'Aggiunto al libro degli incantesimi.':catType==='equipment'||catType==='magicitems'?'Aggiunto all’inventario.':'Aggiunto alle opzioni selezionate.'}
document.addEventListener('click',e=>{let nav=e.target.closest('[data-page="catalog"]');if(nav){loadCatalog();return}let b=e.target.closest('button');if(!b)return;if(b.dataset.catIndex)openCatItem(b.dataset.catIndex);if(b.id==='catRetry')loadCatalog();if(b.id==='catAdd')addCatalog();if(b.dataset.catRemove!==undefined){state.catalog.splice(Number(b.dataset.catRemove),1);save();$('#catalog-saved').innerHTML=savedCatalog()}});
document.addEventListener('change',e=>{if(e.target.id==='catType'){catType=e.target.value;catQuery='';catLevel='';catClass='';render();loadCatalog()}if(e.target.id==='catLevel'){catLevel=e.target.value;loadCatalog()}if(e.target.id==='catClass'){catClass=e.target.value;loadCatalog()}});
document.addEventListener('input',e=>{if(e.target.id==='catSearch'){catQuery=e.target.value;drawCatalog()}});
